import java.util.*;

public class Main {
    static class Node {
        int k, v; Node prev, next;
        Node(int k, int v) { this.k = k; this.v = v; }
    }
    static class LRU {
        int cap;
        Map<Integer, Node> map = new HashMap<>();
        Node head = new Node(0, 0), tail = new Node(0, 0);   // sentinels
        LRU(int cap) { this.cap = cap; head.next = tail; tail.prev = head; }
        void unlink(Node n) { n.prev.next = n.next; n.next.prev = n.prev; }
        void front(Node n) {                                  // most recent after head
            n.next = head.next; n.prev = head;
            head.next.prev = n; head.next = n;
        }
        int get(int k) {                                      // O(1)
            Node n = map.get(k);
            if (n == null) return -1;
            unlink(n); front(n);
            return n.v;
        }
        void put(int k, int v) {                              // O(1)
            Node n = map.get(k);
            if (n != null) { n.v = v; unlink(n); front(n); return; }
            if (map.size() == cap) {                          // evict least recent
                Node last = tail.prev;
                unlink(last); map.remove(last.k);
            }
            n = new Node(k, v); map.put(k, n); front(n);
        }
    }
    public static void main(String[] args) {
        LRU c = new LRU(2);
        System.out.println("capacity=2");
        c.put(1, 1); c.put(2, 2);
        System.out.println("get 1 -> " + c.get(1));
        c.put(3, 3);
        System.out.println("get 2 -> " + c.get(2));
        c.put(4, 4);
        System.out.println("get 1 -> " + c.get(1));
        System.out.println("get 3 -> " + c.get(3));
        System.out.println("get 4 -> " + c.get(4));
    }
}

