class Node {
  constructor(k, v) { this.k = k; this.v = v; this.prev = null; this.next = null; }
}
class LRU {
  constructor(cap) {
    this.cap = cap; this.map = new Map();
    this.head = new Node(0, 0); this.tail = new Node(0, 0);   // sentinels
    this.head.next = this.tail; this.tail.prev = this.head;
  }
  unlink(n) { n.prev.next = n.next; n.next.prev = n.prev; }
  front(n) {                                  // most recent sits after head
    n.next = this.head.next; n.prev = this.head;
    this.head.next.prev = n; this.head.next = n;
  }
  get(k) {                                    // O(1)
    const n = this.map.get(k);
    if (!n) return -1;
    this.unlink(n); this.front(n);
    return n.v;
  }
  put(k, v) {                                 // O(1)
    let n = this.map.get(k);
    if (n) { n.v = v; this.unlink(n); this.front(n); return; }
    if (this.map.size === this.cap) {         // evict least recent
      const last = this.tail.prev;
      this.unlink(last); this.map.delete(last.k);
    }
    n = new Node(k, v); this.map.set(k, n); this.front(n);
  }
}
