#include <bits/stdc++.h>
using namespace std;

struct Node {
    int k, v; Node *prev = nullptr, *next = nullptr;
    Node(int k, int v) : k(k), v(v) {}
};
struct LRU {
    int cap;
    unordered_map<int, Node*> mp;
    Node head{0, 0}, tail{0, 0};                       // sentinels
    LRU(int cap) : cap(cap) { head.next = &tail; tail.prev = &head; }
    void unlink(Node* n) { n->prev->next = n->next; n->next->prev = n->prev; }
    void front(Node* n) {                              // most recent after head
        n->next = head.next; n->prev = &head;
        head.next->prev = n; head.next = n;
    }
    int get(int k) {                                   // O(1)
        auto it = mp.find(k);
        if (it == mp.end()) return -1;
        unlink(it->second); front(it->second);
        return it->second->v;
    }
    void put(int k, int v) {                           // O(1)
        auto it = mp.find(k);
        if (it != mp.end()) { it->second->v = v; unlink(it->second); front(it->second); return; }
        if ((int)mp.size() == cap) {                   // evict least recent
            Node* last = tail.prev;
            unlink(last); mp.erase(last->k); delete last;
        }
        Node* n = new Node(k, v); mp[k] = n; front(n);
    }
};
int main() {
    LRU c(2);
    cout << "capacity=2" << endl;
    c.put(1, 1); c.put(2, 2);
    cout << "get 1 -> " << c.get(1) << endl;
    c.put(3, 3);
    cout << "get 2 -> " << c.get(2) << endl;
    c.put(4, 4);
    cout << "get 1 -> " << c.get(1) << endl;
    cout << "get 3 -> " << c.get(3) << endl;
    cout << "get 4 -> " << c.get(4) << endl;
}

