using System;
using System.Collections.Generic;

class Node {
    public int K, V; public Node Prev, Next;
    public Node(int k, int v) { K = k; V = v; }
}
class LRU {
    int cap;
    Dictionary<int, Node> map = new Dictionary<int, Node>();
    Node head = new Node(0, 0), tail = new Node(0, 0);      // sentinels
    public LRU(int cap) { this.cap = cap; head.Next = tail; tail.Prev = head; }
    void Unlink(Node n) { n.Prev.Next = n.Next; n.Next.Prev = n.Prev; }
    void Front(Node n) {                                    // most recent after head
        n.Next = head.Next; n.Prev = head;
        head.Next.Prev = n; head.Next = n;
    }
    public int Get(int k) {                                 // O(1)
        Node n;
        if (!map.TryGetValue(k, out n)) return -1;
        Unlink(n); Front(n);
        return n.V;
    }
    public void Put(int k, int v) {                         // O(1)
        Node n;
        if (map.TryGetValue(k, out n)) { n.V = v; Unlink(n); Front(n); return; }
        if (map.Count == cap) {                             // evict least recent
            Node last = tail.Prev;
            Unlink(last); map.Remove(last.K);
        }
        n = new Node(k, v); map[k] = n; Front(n);
    }
}
class Program {
    static void Main() {
        LRU c = new LRU(2);
        Console.WriteLine("capacity=2");
        c.Put(1, 1); c.Put(2, 2);
        Console.WriteLine("get 1 -> " + c.Get(1));
        c.Put(3, 3);
        Console.WriteLine("get 2 -> " + c.Get(2));
        c.Put(4, 4);
        Console.WriteLine("get 1 -> " + c.Get(1));
        Console.WriteLine("get 3 -> " + c.Get(3));
        Console.WriteLine("get 4 -> " + c.Get(4));
    }
}
